// The CSVs live in a dated subfolder of the Drive folder, not loose in it.
// This picks which subfolder today's run reads.
//
// WHY THE FOLDER NAME IS THE DATE, AND NOT THE FILE'S TIMESTAMP
// The old workflow took run_date from the filename, falling back to Drive's
// modifiedTime. Most scraper filenames carry no date, so the fallback did the
// work - and anything uploaded after midnight carries the next day's timestamp.
// One late upload put a whole day of stores on the wrong run_date. The folder
// is named for the day it belongs to, so that is the only thing asked.

const TZ       = 'Asia/Karachi';   // the clock the folder names are written against
const OVERRIDE = '';               // set to 'YYYY-MM-DD' to replay one specific day

const folders = $input.all()
  .flatMap(i => i.json.files || [])
  .filter(f => /^\d{4}-\d{2}-\d{2}$/.test(f.name));

if (!folders.length) {
  throw new Error('No dated (YYYY-MM-DD) subfolder found in the Drive parent folder. Nothing to ingest.');
}

const today = OVERRIDE || new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());

// Newest first, so the fallback below is the most recent day.
folders.sort((a, b) => b.name.localeCompare(a.name));

const exact  = folders.find(f => f.name === today);
const chosen = exact || folders[0];

// Falling back rather than stopping: a run that starts a few minutes after
// midnight, or a scraper that finished late, should still ingest the day that
// is actually there instead of reporting nothing and looking like a success.
if (!exact) {
  console.log(`No folder named ${today} - using the newest one instead: ${chosen.name}`);
}
console.log(`Ingesting from folder ${chosen.name}`);

return [{ json: {
  folder_id:   chosen.id,
  folder_name: chosen.name,
  run_date:    chosen.name,
  exact_date:  Boolean(exact),
} }];

// Match every CSV in the day's folder to a store, and drop the ones already
// recorded. The csv_prefix rules are the same as scripts/ingest-drive.mjs.
//
// run_date comes from the FOLDER, not from the file - see the note in
// "Pick the day's folder".

// Flip to true for a one-off replay of a date that is already recorded.
// Only a store's NEWEST date can be replayed: ingest_store_day() rewinds that
// run and redoes it. An older date is refused by the database rather than
// merged, because the current-state layer holds the newest values and diffing
// an older file against them would write nonsense.
const FORCE = false;

const files  = $('List the day\'s CSVs').all().flatMap(i => i.json.files || []);
const folder = $('Pick the day\'s folder').first().json;
const meta   = $input.first().json.meta;
const stores = meta.stores || [];
const done   = new Set((meta.done || []).map(String));

const run_date = folder.run_date;

/** Longest matching csv_prefix wins, so similar domains cannot collide.
 *
 *  Both sides have their www dropped before comparing. This is not cosmetic:
 *  the scraper stopped putting www in the filename on 7 Aug - 6 Aug has
 *  https___www_1822denim_com_shopify.csv and every day after it has
 *  https___1822denim_com_shopify.csv - while the sheet still spells 74 of the
 *  242 stores with www. Matching literally skipped 70 files, 65 of them a whole
 *  day for stores that are very much in the sheet, and skipped them silently.
 *  Copied from scripts/ingest-folder.mjs so the two paths agree.
 */
const noWww = s => String(s).toLowerCase().replace(/^https___www_/, 'https___');

const storeFor = name => {
  const f = noWww(name);
  return stores
    .filter(s => s.csv_prefix && f.startsWith(noWww(s.csv_prefix)))
    .sort((a, b) => String(b.csv_prefix).length - String(a.csv_prefix).length)[0] || null;
};

// Measured, not guessed. The Code node runs in n8n's task-runner process,
// which starts with node's default heap of 2,096 MB on this server and has no
// --max-old-space-size override. Parsing holds the file several times over:
// the raw text, the parsed rows (mostly cheap V8 slice references into it),
// the product/variant objects, the JSON, and that JSON again inside the SQL
// string. Peak lands around 3x the file size, so ~250 MB is the last size that
// still leaves headroom.
//
// TO LIFT THIS: give n8n a bigger heap and raise the number here. As the user
// that runs n8n (waleed):
//     NODE_OPTIONS=--max-old-space-size=4096
// With 4 GB the whole day fits, including the 368 MB export, and this guard can
// be set to Infinity.
//
// Files over the limit are reported, not silently dropped, and go through
// npm run ingest:server - which streams and never holds the file whole.
const MAX_MB = 250;

const jobs = [], skipped = [], unmatched = [], toobig = [], duplicate = [];
const queued = new Set();

for (const f of files) {
  if (!/\.csv$/i.test(f.name)) continue;
  const store = storeFor(f.name);
  // Never guess. A file matching no store is reported and left alone.
  if (!store) { unmatched.push(f.name); continue; }
  if (!FORCE && done.has(`${store.id}|${run_date}`)) { skipped.push(f.name); continue; }
  const mb = (Number(f.size) || 0) / 1e6;
  if (mb > MAX_MB) { toobig.push(`${f.name} (${mb.toFixed(0)} MB)`); continue; }
  // Two files in one folder can match the same store - a re-upload, or a
  // rename. The done list was read before the loop and cannot see the first
  // one, so without this the second rewinds the run the first just made.
  if (queued.has(`${store.id}|${run_date}`)) { duplicate.push(f.name); continue; }
  queued.add(`${store.id}|${run_date}`);
  jobs.push({
    file_id: f.id, file_name: f.name,
    store_id: store.id, store_name: store.name, run_date,
    mb: ((Number(f.size) || 0) / 1e6).toFixed(1),
  });
}

console.log('==================== PLAN ====================');
console.log(`  folder             ${run_date}`);
console.log(`  files in folder    ${files.length}`);
console.log(`  already in the db  ${skipped.length}`);
console.log(`  unmatched          ${unmatched.length}`);
console.log(`  duplicate in run   ${duplicate.length}`);
console.log(`  too large          ${toobig.length}`);
console.log(`  LEFT TO INGEST     ${jobs.length}`);
console.log('==============================================');
if (unmatched.length) console.log('unmatched (no store csv_prefix matches):', unmatched.join(', '));
if (skipped.length)   console.log('already ingested:', skipped.join(', '));
if (duplicate.length) console.log('another file already covers that store today:', duplicate.join(', '));
if (toobig.length)    console.log(`too large for a Code node (> ${MAX_MB} MB) - ingest these with npm run ingest:server:`, toobig.join(', '));
if (!jobs.length)     console.log('Nothing new to ingest - the run ends here.');

// ── how many this execution takes on ─────────────────────────────
// n8n keeps every node's output for every item until the execution ends - the
// whole CSV text from the download AND the JSON-carrying SQL from the parser.
// That is cumulative, not per file: on 3 Sep the run died at the 44th file with
// roughly 1.1 GB held, having handled a 70,000-row store without trouble a
// minute earlier. The file size was never the problem; the pile was.
//
// So each execution takes a bite and stops. When it ends n8n frees the lot, and
// the next one picks up from the database's own record of what is done. 25 is
// a little over half the size that failed.
//
// At the measured 20.4 s per file that is ~8.5 minutes of work, which is why
// the schedule below it is 15 minutes: finished, and its memory returned, well
// before the next one starts.
const MAX_FILES_PER_RUN = 25;

const batch     = jobs.slice(0, MAX_FILES_PER_RUN);
const remaining = jobs.length - batch.length;

console.log(`THIS RUN takes ${batch.length} file(s)` +
            (remaining > 0 ? `; ${remaining} left for the next run` : ' - the last of them'));

return batch.map(j => ({ json: { ...j, _skipped: skipped, _unmatched: unmatched,
                                _toobig: toobig, _duplicate: duplicate,
                                _remaining: remaining, _folder: run_date } }));

// One line per store: what went in, what failed, what was skipped.

const ok = $('Run ingest_store_day').all().map(i => {
  const r = i.json.result;
  return typeof r === 'string' ? JSON.parse(r) : r;
}).filter(Boolean);

// The failure node only exists in the run if something actually failed, so
// asking for it unconditionally would itself throw.
let failures = [];
try {
  failures = $('Record the failure').all().map(i => i.json).filter(f => f && f.failed);
} catch (e) {
  failures = [];
}

const jobs  = $('Decide what to ingest').all().map(i => i.json);
const first = jobs[0] || {};

// A run the database refused as already done is not a success and not a
// failure - it is work that was correctly not repeated.
const redone = ok.filter(r => r.status === 'already_done');
const real   = ok.filter(r => r.status !== 'already_done');

const okLines = real.map(r => {
  const job = jobs.find(j => Number(j.store_id) === Number(r.store_id) && j.run_date === r.run_date);
  const name = job ? job.store_name : `store ${r.store_id}`;
  const counts = Object.entries(r.counts || {}).map(([k, v]) => `${k} ${v}`).join(', ');
  return `${r.status === 'success' ? 'OK  ' : 'PART'} ${name} - ${r.run_date} - ${r.changes} changes` +
         (counts ? ` (${counts})` : '') +
         (r.removals_skipped ? '  [feed collapsed, removals skipped]' : '');
});

const failLines = failures.map(f => `FAIL ${f.store_name || f.file_name} - ${f.run_date} - ${f.reason}`);

console.log([...okLines, ...failLines].join('\n') || 'nothing was ingested');
console.log('=================== RESULT ===================');
console.log(`  ingested this run  ${real.length}`);
console.log(`  failed             ${failures.length}`);
console.log(`  partial            ${real.filter(r => r.status !== 'success').length}`);
console.log(`  refused as done    ${redone.length}`);
console.log(`  total changes      ${real.reduce((n, r) => n + (r.changes || 0), 0)}`);
console.log(`  STILL TO GO        ${first._remaining ?? 0}`);
if (failures.length) {
  console.log('  --- failures ---');
  for (const f of failures) console.log(`   ${f.store_name || f.file_name}  [${f.stage || '?'}]  ${f.reason}`);
}
console.log('==============================================');

return [{ json: {
  folder:          first._folder || null,
  ingested:        real.length,
  skipped_in_db:   redone.length,
  failed:          failures.length,
  partial:         real.filter(r => r.status !== 'success').length,
  total_changes:   real.reduce((n, r) => n + (r.changes || 0), 0),
  already_done:    first._skipped   || [],
  unmatched:       first._unmatched || [],
  too_large:       first._toobig    || [],
  duplicate_files: first._duplicate || [],
  still_to_go:     first._remaining ?? 0,
  stores:          okLines,
  failures:        failLines,
  results:         real,
  failure_details: failures,
} }];

// Parse the CSV and build the one statement that does the whole ingest.
//
// Everything above the divider is lib/csv-to-payload.mjs verbatim — the Code
// node cannot require csv-parse, and a test runs both over the same bytes and
// checks they agree. The diff itself is NOT here: it lives in
// ingest_store_day(), so n8n and scripts/ingest.mjs cannot drift apart.

/**
 * RFC 4180. Quoted fields may hold commas, newlines and doubled quotes, and
 * Shopify's Body (HTML) column holds all three.
 *
 * A quote only opens a quoted field at the start of one. Mid-field quotes are
 * literal — csv-parse behaves this way under relax_quotes, and product
 * descriptions contain plenty of stray inch marks.
 *
 * Written around indexOf/slice rather than a character loop. The character
 * version was clear but did ~8 million iterations on a 7.9 MB export, and the
 * n8n Code node runs inside a sandboxed VM where that took minutes. indexOf and
 * slice are native, so the sandbox barely slows them down.
 */
function parseCsv (text) {
  const src = String(text).replace(/^﻿/, '')
  const n = src.length
  const rows = []
  let row = []
  let i = 0

  while (i < n) {
    let field

    if (src[i] === '"') {
      // Quoted: hop from quote to quote. A doubled quote is an escaped one and
      // the field continues; a lone quote ends it.
      let j = i + 1
      let buf = null                      // stays null while there is no escape
      let start = j
      for (;;) {
        const k = src.indexOf('"', j)
        if (k < 0) { field = (buf ?? '') + src.slice(start); i = n; break }
        if (src[k + 1] === '"') {
          buf = (buf ?? '') + src.slice(start, k + 1)
          j = k + 2
          start = j
          continue
        }
        field = buf === null ? src.slice(start, k) : buf + src.slice(start, k)
        i = k + 1
        break
      }
    } else {
      // Unquoted: run to whichever delimiter comes first.
      let c = src.indexOf(',', i); if (c < 0) c = n
      let l = src.indexOf('\n', i); if (l < 0) l = n
      const end = c < l ? c : l
      field = src.slice(i, end)
      if (field.charCodeAt(field.length - 1) === 13) field = field.slice(0, -1)  // trailing \r
      i = end
    }

    row.push(field)

    if (i >= n) break
    if (src[i] === ',') { i++; continue }
    if (src[i] === '\r') i++
    if (src[i] === '\n') { rows.push(row); row = []; i++; continue }
    // A stray character after a closing quote: skip to the next delimiter
    // rather than losing the rest of the file to it.
    let c = src.indexOf(',', i); if (c < 0) c = n
    let l = src.indexOf('\n', i); if (l < 0) l = n
    if (c < l) { i = c + 1 } else { rows.push(row); row = []; i = l + 1 }
  }

  if (row.length) rows.push(row)
  return rows
}

const s = v => (v ?? '').toString().trim()

const num = v => {
  const n = parseFloat(String(v ?? '').replace(/,/g, ''))
  return Number.isFinite(n) ? n : null
}

/** Blank = sellable, explicit 0 = sold out, a real number = that many left. */
const available = raw => {
  const t = s(raw)
  if (t === '') return true
  const n = Number(t)
  return Number.isFinite(n) ? n > 0 : true
}

/**
 * The raw Inventory quantity, or null when the store gave nothing usable. A 0
 * is a state marker, not a count — it says the variant sold out, never how many
 * there had been, so it is not reported as a quantity.
 */
const qty = raw => {
  const t = s(raw)
  if (t === '') return null
  const n = Number(t)
  return Number.isFinite(n) && n > 0 ? Math.trunc(n) : null
}

function csvToPayload (text) {
  const rows = parseCsv(text)
  if (!rows.length) return { products: [], variants: [], rows: 0 }

  // Column positions are resolved once. Looking each cell up by name meant a
  // string lookup and a closure call ~20 times per row across tens of thousands
  // of rows — cheap natively, and not cheap inside the sandbox the n8n Code
  // node runs in.
  const idx = {}
  rows[0].forEach((h, n) => { const k = s(h); if (!(k in idx)) idx[k] = n })
  const at = name => (name in idx ? idx[name] : -1)

  const iHandle  = at('Handle')
  const iTitle   = at('Title')
  const iVendor  = at('Vendor')
  const iType    = at('Type')
  const iTags    = at('Tags')
  const iPub     = at('Published')
  const iStatus  = at('Status')
  const iImage   = at('Image Src')
  const iSku     = at('Variant SKU')
  const iPrice   = at('Variant Price')
  const iCompare = at('Variant Compare At Price')
  const iVImage  = at('Variant Image')
  const iInv     = at('Inventory quantity')
  // Present only on exports the scraper marked. A missing column stays null
  // rather than becoming a store-wide false, exactly as ingest.mjs treats it.
  const iTop     = at('Top 20 Selling Product')
  const iO1n = at('Option1 Name'), iO1v = at('Option1 Value')
  const iO2n = at('Option2 Name'), iO2v = at('Option2 Value')
  const iO3n = at('Option3 Name'), iO3v = at('Option3 Value')

  const g = (row, i) => (i < 0 ? '' : s(row[i]))

  const products = new Map()   // handle          -> product
  const variants = new Map()   // handle\0key     -> variant
  let dataRows = 0

  for (let r = 1; r < rows.length; r++) {
    const row = rows[r]
    // csv-parse's skip_empty_lines drops a blank line, which this parser
    // returns as a single empty field. A row of genuinely empty columns is a
    // real row and stays counted, exactly as csv-parse counts it.
    if (row.length === 1 && row[0] === '') continue
    dataRows++

    const handle = g(row, iHandle)
    if (!handle) continue

    // The parent row carries the product-level fields; image-only rows that
    // follow it may still be the first to name an image.
    const title = g(row, iTitle)
    if (title) {
      const tags = g(row, iTags)
      products.set(handle, {
        handle,
        title,
        vendor:       g(row, iVendor) || null,
        product_type: g(row, iType) || null,
        tags:         tags ? tags.split(',').map(t => t.trim()).filter(Boolean) : [],
        published:    g(row, iPub) || null,
        status:       g(row, iStatus) || null,
        image_src:    g(row, iImage) || null,
        is_top_seller: iTop < 0 ? null : /^y/i.test(g(row, iTop)),
      })
    } else {
      const p = products.get(handle)
      if (p && !p.image_src) {
        const img = g(row, iImage)
        if (img) p.image_src = img
      }
    }

    // a variant row has a SKU or a price
    const sku   = g(row, iSku)
    const price = g(row, iPrice)
    if (!sku && !price) continue

    const o1 = g(row, iO1v), o2 = g(row, iO2v), o3 = g(row, iO3v)
    const variant_key = [sku, o1, o2, o3].join('|')   // SKUs repeat; options disambiguate
    const key = handle + '�' + variant_key
    if (variants.has(key)) continue

    const inv = iInv < 0 ? '' : row[iInv]
    variants.set(key, {
      handle, variant_key,
      sku: sku || null,
      option1_name: g(row, iO1n) || null, option1_value: o1 || null,
      option2_name: g(row, iO2n) || null, option2_value: o2 || null,
      option3_name: g(row, iO3n) || null, option3_value: o3 || null,
      variant_image: g(row, iVImage) || null,
      price: num(price),
      compare_at: num(iCompare < 0 ? '' : row[iCompare]),
      // Inventory quantity does carry the stock signal: blank means sellable,
      // an explicit 0 means sold out. Checked against the store's live
      // /products.json feed — 99.2% agreement over 3,406 variants.
      available: available(inv),
      qty: qty(inv),
    })
  }

  return {
    products: [...products.values()],
    variants: [...variants.values()],
    rows: dataRows,
  }
}

// ── build the statement ───────────────────────────────────────────
// batchSize is 1, so the loop node is holding exactly this file's job.
const job = $('Loop over files').first().json;
const csv = $input.first().json.csv ?? $input.first().json.data ?? '';

if (!/^\d{4}-\d{2}-\d{2}$/.test(String(job.run_date))) {
  throw new Error(`refusing to build SQL for a run_date that is not YYYY-MM-DD: ${job.run_date}`);
}
const storeId = Number(job.store_id);
if (!Number.isInteger(storeId)) throw new Error(`store_id is not a number: ${job.store_id}`);

const payload = csvToPayload(csv);
if (!payload.variants.length) {
  throw new Error(`${job.file_name} parsed to 0 variants — refusing to send an empty payload`);
}

// Dollar quoting carries any JSON safely; the tag cannot occur inside JSON,
// because $ing$ is not a sequence JSON.stringify can emit.
const json = JSON.stringify(payload);
const quoted = str => "'" + String(str).replace(/'/g, "''") + "'";

// The list of finished runs was read once, before the loop. It cannot know
// about a run that finished a minute ago in a parallel execution, or about the
// file two positions earlier in this same loop. So the last word is asked of
// the database, inside the same statement that would do the work: if a
// success or partial already exists for this store and date, the function is
// never called.
//
// CASE does not evaluate its ELSE branch when the WHEN matches, and
// ingest_store_day() is VOLATILE so it is never folded in early. The shape
// returned matches the function's own, so the Summary reads both the same way.
const sql =
  `SELECT CASE WHEN EXISTS (SELECT 1 FROM scrape_runs ` +
  `WHERE store_id = ${storeId} AND run_date = ${quoted(job.run_date)}::date ` +
  `AND status IN ('success','partial')) ` +
  `THEN jsonb_build_object('status','already_done','store_id',${storeId},` +
  `'run_date',${quoted(job.run_date)},'changes',0,'counts','{}'::jsonb) ` +
  `ELSE ingest_store_day(${storeId}, ${quoted(job.run_date)}, ${quoted(job.file_name)}, ` +
  `${payload.rows}, $ing$${json}$ing$::jsonb) END AS result`;

// ingest_store_day() DOES set products.is_top_seller from the payload - it
// reads the column and honours the "only an export that carries it may
// overwrite" rule itself. What it does not do is keep the daily history, and
// scripts/ingest.mjs does: without this the frontend loses the record of when
// a product entered or left the top 20.
//
// The run row was created by the function a moment ago, so it is looked up by
// (store, date) rather than threaded through - that pair is unique.
const marked = payload.products.filter(p => p.is_top_seller === true);
let sqlTop = 'SELECT 1';            // a no-op, so the node always has a statement
if (marked.length) {
  const handles = marked.map(p => quoted(p.handle)).join(',');
  sqlTop =
    `INSERT INTO product_top_sellers (product_id, scrape_run_id, observed_date) ` +
    `SELECT p.id, r.id, ${quoted(job.run_date)}::date FROM products p ` +
    `CROSS JOIN LATERAL (SELECT id FROM scrape_runs WHERE store_id = ${storeId} ` +
    `AND run_date = ${quoted(job.run_date)}::date) r ` +
    `WHERE p.store_id = ${storeId} AND p.handle = ANY(ARRAY[${handles}]::text[]) ` +
    `ON CONFLICT (product_id, observed_date) DO NOTHING`;
}

// $runIndex counts this node's turns inside the loop, so it is the file's
// number within this execution; the total is what the plan handed the loop.
const total = $('Decide what to ingest').all().length;
console.log(`[${$runIndex + 1}/${total}] ${job.store_name} - ${job.file_name}`);
console.log(`          ${payload.rows} rows -> ${payload.products.length} products, ` +
            `${payload.variants.length} variants` +
            (marked.length ? `, ${marked.length} top-20` : ''));

return [{ json: { ...job, products: payload.products.length,
                  variants: payload.variants.length,
                  top_sellers: marked.length,
                  sql, sqlTop } }];

// One file's failure, written down so the loop can carry on to the next store.
//
// The error outputs of "Download the CSV", "Parse CSV and build the ingest" and
// "Run ingest_store_day" all arrive here. Before this existed, the first bad
// CSV ended the whole run and every store after it was never attempted.

const job = $('Loop over files').first().json;

// The error's shape differs between an HTTP node, a Code node and the Postgres
// node, so every form it takes is checked.
const raw = $json.error?.message
         ?? $json.error?.description
         ?? $json.error
         ?? $json.message
         ?? 'unknown error';

// One line, always. These messages carry stack traces, SQL fragments and
// newlines, and a multi-line reason wrecks the summary and anything it is
// written into afterwards.
const reason = String(raw).replace(/\s+/g, ' ').trim().slice(0, 500);

// Three nodes feed this one and n8n does not always name which. What did and
// did not reach the item says it exactly: no csv at all means the download
// never returned; a csv with no sql means the parser threw; an item that
// carries sql got as far as the database.
let stage;
if      ($json.csv === undefined && $json.sql === undefined) stage = 'Download the CSV';
else if ($json.sql === undefined)                            stage = 'Parse CSV and build the ingest';
else                                                         stage = 'Run ingest_store_day / Write top sellers';
if ($json.error?.node?.name) stage = $json.error.node.name;   // believe n8n over the guess

console.log(`  !! FAILED at [${stage}]`);
console.log(`     store  ${job.store_name || '?'} (${job.store_id ?? '?'})`);
console.log(`     file   ${job.file_name || '?'}`);
console.log(`     reason ${reason}`);

return [{ json: {
  failed:     true,
  store_id:   job.store_id,
  store_name: job.store_name,
  file_name:  job.file_name,
  stage,
  run_date:   job.run_date,
  reason,
} }];
